<section><h2 class="mb-4 text-lg font-semibold">Menunggu persetujuan saya</h2><div class="overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-sm"><table class="w-full min-w-[48rem] text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-600"><tr><th class="px-5 py-3">Permintaan</th><th class="px-5 py-3">Pemohon</th><th class="px-5 py-3">Alur / tahap</th><th class="px-5 py-3">Tindakan</th></tr></thead><tbody class="divide-y divide-slate-100"><?php if (!$approval_can_update): ?><tr><td colspan="4" class="px-5 py-10 text-center text-slate-500">Anda tidak memiliki izin untuk mengambil keputusan.</td></tr><?php elseif (!$approval_requests): ?><tr><td colspan="4" class="px-5 py-10 text-center text-slate-500">Tidak ada permintaan yang menunggu Anda.</td></tr><?php else: foreach ($approval_requests as $request): ?><tr><th scope="row" class="px-5 py-4 font-medium"><div><?= html_escape($request['subject']) ?></div><p class="mt-1 max-w-md whitespace-pre-wrap text-xs font-normal text-slate-600"><?= html_escape($request['details']) ?></p></th><td class="px-5 py-4"><?= html_escape($request['requester_name'] ?: '—') ?></td><td class="px-5 py-4"><?= html_escape($request['flow_name']) ?><div class="text-xs text-slate-500">Tahap <?= (int)$request['current_step'] ?></div></td><td class="px-5 py-4"><form method="post" action="/admin/system/approval/decide" class="flex flex-col gap-2"><input type="hidden" name="<?= html_escape($csrf_token_name) ?>" value="<?= html_escape($csrf_hash) ?>"><input type="hidden" name="request_id" value="<?= (int)$request['request_id'] ?>"><label class="sr-only" for="note-<?= (int)$request['request_id'] ?>">Catatan keputusan</label><input id="note-<?= (int)$request['request_id'] ?>" name="note" maxlength="1000" placeholder="Catatan (opsional)" class="min-h-9 rounded-lg border border-slate-300 px-2"><div class="flex gap-2"><button name="decision" value="approved" class="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-semibold text-white hover:bg-emerald-700">Setujui</button><button name="decision" value="rejected" class="rounded-lg bg-rose-600 px-3 py-2 text-xs font-semibold text-white hover:bg-rose-700">Tolak</button></div></form></td></tr><?php endforeach; endif; ?></tbody></table></div></section><?php endif; ?></main>
